import{_ as a,c as i,o as r,ag as t}from"./chunks/framework.ARG558ZT.js";const m=JSON.parse('{"title":"Embeddings, Similarity and Compatible Search Spaces — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/applied-ai/chapters/embeddings-and-similarity.md","filePath":"practice/applied-ai/chapters/embeddings-and-similarity.md"}'),n={name:"practice/applied-ai/chapters/embeddings-and-similarity.md"};function s(c,e,o,d,l,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="embeddings-similarity-and-compatible-search-spaces-—-practice" tabindex="-1">Embeddings, Similarity and Compatible Search Spaces — practice <a class="header-anchor" href="#embeddings-similarity-and-compatible-search-spaces-—-practice" aria-label="Permalink to “Embeddings, Similarity and Compatible Search Spaces — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These requirements were separated from the textbook. Use the <a href="./../">integrated sequence</a> and shared evidence record; running reference checks is not independent completion.</p><p><a href="./../../../python-for-ai/embeddings-and-similarity.html">Textbook</a></p><h3 id="practice-for-hybrid-search" tabindex="-1">Practice for hybrid search <a class="header-anchor" href="#practice-for-hybrid-search" aria-label="Permalink to “Practice for hybrid search”">​</a></h3><p>Create a labeled set containing an exact error-code query, a paraphrase, a negation, a multilingual query and a no-answer query. Compare lexical-only, semantic-only and hybrid rankings while retaining per-branch candidate IDs. Vary candidate depth, top-k, branch thresholds and fusion weights one factor at a time. Measure relevant-item recall and misleading retrieved items under the actual permission filters, then evaluate the final cited answer separately.</p><p><strong>Acceptance:</strong> baseline/fusion tests and strict checks pass; empty branches, ties, duplicate IDs, forbidden candidates, invalid policies and nonfinite thresholds are explicit; exact identifiers/Unicode normalization behave as documented; you can explain why raw score addition and copying thresholds between stages are invalid. Real embedding relevance, production sparse/ANN adapters, learned reranking and learner measurements remain unperformed. The current official hosted Retrieval guide also describes hybrid weighting, but this local formula is an independent reference, not a claim to reproduce its internals. <a href="https://developers.openai.com/api/docs/guides/retrieval" target="_blank" rel="noreferrer">Official retrieval ranking guidance</a>.</p><h2 id="practice-and-acceptance" tabindex="-1">Practice and acceptance <a class="header-anchor" href="#practice-and-acceptance" aria-label="Permalink to “Practice and acceptance”">​</a></h2><p>Compute cosine for identical, orthogonal and opposite vectors; explain why scaling one vector changes dot product but not cosine. Run the tiny search tests, then add zero/nonfinite/wrong-dimension store records, empty authorized results, invalid thresholds/top_k, dimension-equivalent incompatible model versions and permission revocation fixtures. No unauthorized ID/title/content should leave the retrieval boundary or consume the top-k limit.</p><p>Build a small reviewed set of real queries and relevant source/chunk IDs. Generate embeddings only in a separately authorized, budgeted integration with non-sensitive fixtures; record model/preprocessing/dimension/source versions. Compare lexical and semantic results by relevant-item recall and misleading matches, including negation, Hungarian/English variants and exact code identifiers. Keep quality measurements separate from these hand-vector tests.</p><p><strong>Acceptance:</strong> strict checks/tests pass; normalization/finite/dimension/zero handling is explicit; compatible namespaces and permission-before-top-k behavior match the reference; the real SDK emits the embedding request through a fake transport and closes. Real provider embeddings/token limits, semantic relevance, durable/approximate vector storage, live permission changes/deletion/caching and learner practice remain required. Those later lessons complete the retrieval system; this note supplies its intermediate representation/similarity boundary.</p>',10)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
